SELECT ms.layer_idx, AVG(
    (tr.vol_day / NULLIF(CAST(REPLACE(REPLACE(t.trader_fin_data->>'usd_bal', '$', ''), ',' , '') AS numeric), 0)) * 
    NULLIF(CAST(tr.trade_perf->>'lev_ratio' AS numeric), 0) * 
    NULLIF(CAST(ob.order_metrics->>'mod_freq' AS numeric) / (1 - NULLIF(CAST(ob.order_metrics->>'cancel_pct' AS numeric), 0)), 0)
) as avg_aggression FROM manipulation_signals ms LEFT JOIN trade_records tr ON ms."REC_TAG" = tr."REC_KEY" LEFT JOIN traders t ON tr.tr_anchor = t."TR_KEY" LEFT JOIN order_behaviour ob ON ms."REC_TAG" = ob."REC_NODE" WHERE ms.layer_idx IN ('Confirmed', 'Suspected') GROUP BY ms.layer_idx;

